// @generated by:gauntlet run:godseye-local-recovery
import { randomUUID } from "node:crypto";
import { AccessBroker, FoundationEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AccessFixture, accessFixture, prepareAccess } from "./access-helpers.js";
import { fixturePlan } from "./foundations-helpers.js";
import { owner } from "./helpers.js";

describe("durable recovery hold across existing service proofs and Foundation grants", () => {
  let fixture: AccessFixture;
  beforeEach(async () => {
    fixture = await accessFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  async function hold() {
    await fixture.store.db
      .update(schema.environments)
      .set({ kind: "recovery", recoveryHold: true })
      .where(eq(schema.environments.id, fixture.development.id));
  }

  it("T-AC-40 revokes runtime material access from an otherwise valid restored service proof after broker reconstruction", async () => {
    const access = await prepareAccess(fixture),
      before = fixture.materialProvider.reads;
    await hold();
    const restarted = new AccessBroker(fixture.store, fixture.brokerOptions);
    let delivered = false;
    await expect(
      restarted.consumeStatic(access.proof, access.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toBeDefined();
    expect(delivered).toBe(false);
    expect(fixture.materialProvider.reads).toBe(before);
  });

  it("T-AC-40 rechecks recovery hold after awaited material reads before private runtime handoff", async () => {
    const access = await prepareAccess(fixture);
    fixture.materialProvider.beforeRead = hold;
    let delivered = false;
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toBeDefined();
    expect(delivered).toBe(false);
  });

  it("T-AC-40 denies restored task proofs and already issued grants despite valid worker, lease and epoch", async () => {
    const access = await prepareAccess(fixture, { purpose: "deploy", workerId: "held-worker" });
    const plan = await fixturePlan(fixture);
    await fixture.engine.enqueue(owner, plan.id, randomUUID());
    const context = await fixture.engine.claim("held-worker");
    if (!context) throw new Error("Held grant fixture missing");
    await hold();
    let delivered = false;
    const use = { tool: "fixture.publish", destination: "fixture.invalid", costMicros: 10 };
    await expect(
      fixture.broker.consumeTask(access.proof, access.slot.id, context, use, () => {
        delivered = true;
      }),
    ).rejects.toBeDefined();
    await expect(
      fixture.engine.authorizeGrant(context, { ...use, actorId: "held-worker" }),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
    expect(delivered).toBe(false);
    expect((await fixture.engine.getGrant(owner, context.grantId)).usedMicros).toBe(0);
  });

  it("T-AC-40 blocks generic queued execution when recovery hold appears after enqueue", async () => {
    const plan = await fixturePlan(fixture);
    await fixture.engine.enqueue(owner, plan.id, randomUUID());
    await hold();
    expect(await fixture.engine.tick("held-queued-worker")).toBe(false);
    expect(fixture.provider.executions).toEqual([]);
  });

  it("T-AC-40 prevents independent generic FoundationEngine instances from bypassing durable held metadata", async () => {
    await hold();
    const generic = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      adapters: [fixture.provider.adapter],
    });
    await expect(
      generic.createPlan(fixture.freshOwner(), fixture.planInput, randomUUID()),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
  });
  it("T-AC-40 blocks generic reconciliation callbacks when durable hold appears after an unknown effect", async () => {
    fixture.provider.executeWith(async () => ({ status: "unknown", costMicros: 0 }));
    const plan = await fixturePlan(fixture),
      run = await fixture.engine.enqueue(owner, plan.id, randomUUID());
    await fixture.engine.tick("unknown-before-hold-worker");
    await hold();
    await expect(fixture.engine.reconcile(owner, run.id, randomUUID())).rejects.toMatchObject({
      code: "RECOVERY_HOLD",
    });
    expect(fixture.provider.reconciliations).toEqual([]);
    expect((await fixture.engine.getBudget(owner, fixture.project.id)).reservedMicros).toBe(50);
  });

  it("T-AC-40 permits ordinary owner metadata edits while retaining server-owned recovery hold", async () => {
    await hold();
    const project = await fixture.core.getProject(owner, fixture.project.id),
      environment = project.environments.find((item) => item.id === fixture.development.id);
    if (!environment) throw new Error("Held recovery environment missing");
    const saved = await fixture.core.updateEnvironment(
      owner,
      project.id,
      environment.id,
      {
        expectedProjectRevision: project.revision,
        expectedRevision: environment.revision,
        name: "renamed-held-cell",
        expiresAt: null,
        memoryMiB: environment.memoryMiB,
        cpuMilliCores: environment.cpuMilliCores,
        diskGiB: environment.diskGiB,
      },
      randomUUID(),
    );
    expect(saved.environments.find((item) => item.id === environment.id)).toMatchObject({
      name: "renamed-held-cell",
      recoveryHold: true,
    });
    await expect(
      fixture.engine.createPlan(
        fixture.freshOwner(),
        { ...fixture.planInput, expectedRevision: saved.revision },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
  });
});
